import { z } from 'zod'
import { prisma } from '@/lib/prisma'

const prioritySchema = z
  .number({ invalid_type_error: '우선순위는 0~2 사이여야 합니다.' })
  .int('우선순위는 0~2 사이여야 합니다.')
  .min(0, '우선순위는 0~2 사이여야 합니다.')
  .max(2, '우선순위는 0~2 사이여야 합니다.')

export const createTodoSchema = z.object({
  title: z
    .string({ required_error: '제목을 입력하세요.' })
    .min(1, '제목을 입력하세요.')
    .max(200, '제목은 200자 이하로 입력하세요.'),
  description: z
    .string()
    .max(2000, '설명은 2000자 이하로 입력하세요.')
    .nullish(),
  priority: prioritySchema.default(0),
  dueDate: z.coerce.date().nullish(),
})

export const updateTodoSchema = z.object({
  title: z.string().min(1, '제목을 입력하세요.').max(200, '제목은 200자 이하로 입력하세요.').optional(),
  description: z.string().max(2000, '설명은 2000자 이하로 입력하세요.').nullish(),
  priority: prioritySchema.optional(),
  dueDate: z.coerce.date().nullish(),
  completed: z.boolean().optional(),
})

export type CreateTodoInput = z.infer<typeof createTodoSchema>
export type UpdateTodoInput = z.infer<typeof updateTodoSchema>

export interface TodoFilters {
  completed?: boolean
  priority?: number
}

/**
 * TODO를 생성한다. 본인 소유로 자동 연결한다.
 */
export async function createTodo(userId: string, input: CreateTodoInput) {
  return prisma.todo.create({
    data: {
      ...input,
      userId,
      dueDate: input.dueDate ?? null,
      description: input.description ?? null,
    },
  })
}

/**
 * 본인 TODO 목록을 필터와 정렬 조회한다.
 * 정렬: 완료 항목을 하단으로, dueDate 오름차순, 마감일 없는 항목은 뒤로.
 */
export async function getTodos(userId: string, filters: TodoFilters = {}) {
  const where: { userId: string; completed?: boolean; priority?: number } = { userId }
  if (filters.completed !== undefined) where.completed = filters.completed
  if (filters.priority !== undefined) where.priority = filters.priority

  return prisma.todo.findMany({
    where,
    orderBy: [
      { completed: 'asc' },
      { dueDate: { sort: 'asc', nulls: 'last' } },
    ],
  })
}

/**
 * 본인 TODO 단건 조회. 존재하지 않거나 소유자가 아니면 null.
 */
export async function getTodo(userId: string, id: string) {
  return prisma.todo.findFirst({
    where: { id, userId },
  })
}

/**
 * 본인 TODO 수정. 존재하지 않거나 소유자가 아니면 null.
 */
export async function updateTodo(userId: string, id: string, input: UpdateTodoInput) {
  const todo = await prisma.todo.findFirst({ where: { id, userId } })
  if (!todo) return null

  const data: Record<string, unknown> = {}
  if (input.title !== undefined) data.title = input.title
  if (input.description !== undefined) data.description = input.description ?? null
  if (input.priority !== undefined) data.priority = input.priority
  if (input.dueDate !== undefined) data.dueDate = input.dueDate ?? null
  if (input.completed !== undefined) data.completed = input.completed

  return prisma.todo.update({
    where: { id },
    data,
  })
}

/**
 * 본인 TODO 삭제. hard delete. 존재하지 않거나 소유자가 아니면 null.
 */
export async function deleteTodo(userId: string, id: string) {
  const todo = await prisma.todo.findFirst({ where: { id, userId } })
  if (!todo) return null

  return prisma.todo.delete({
    where: { id },
  })
}

import { Request, Response, NextFunction, Router } from 'express'
import { z } from 'zod'
import { requireAuth } from '@/middleware/auth'
import {
  createTodo,
  getTodo,
  getTodos,
  updateTodo,
  deleteTodo,
  createTodoSchema,
  updateTodoSchema,
} from '@/services/todo'

const router = Router()

type AsyncHandler = (req: Request, res: Response, _next: NextFunction) => Promise<void>

function asyncRoute(handler: AsyncHandler) {
  return (req: Request, res: Response, next: NextFunction) => {
    handler(req, res, next).catch(next)
  }
}

const listQuerySchema = z.object({
  completed: z
    .enum(['true', 'false'])
    .optional()
    .transform((v) => (v === 'true' ? true : v === 'false' ? false : undefined)),
  priority: z.coerce.number().int().min(0).max(2).optional(),
})

/**
 * GET /api/todos
 * 본인 TODO 목록 조회. completed/priority 쿼리 필터 지원.
 */
router.get(
  '/',
  requireAuth,
  asyncRoute(async (req, res) => {
    const userId = req.user!.id
    const parsed = listQuerySchema.safeParse(req.query)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    const { completed, priority } = parsed.data
    const todos = await getTodos(userId, { completed, priority })
    res.json({ todos })
  }),
)

/**
 * GET /api/todos/:id
 * 본인 TODO 단건 조회.
 */
router.get(
  '/:id',
  requireAuth,
  asyncRoute(async (req, res) => {
    const userId = req.user!.id
    const todo = await getTodo(userId, req.params.id)
    if (!todo) {
      res.status(404).json({ error: 'TODO를 찾을 수 없습니다.' })
      return
    }
    res.json({ todo })
  }),
)

/**
 * POST /api/todos
 * TODO 생성. priority는 0~2, dueDate 선택.
 */
router.post(
  '/',
  requireAuth,
  asyncRoute(async (req, res) => {
    const userId = req.user!.id
    const parsed = createTodoSchema.safeParse(req.body)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    const todo = await createTodo(userId, parsed.data)
    res.status(201).json({ todo })
  }),
)

/**
 * PUT /api/todos/:id
 * TODO 수정. 본인 TODO만 가능.
 */
router.put(
  '/:id',
  requireAuth,
  asyncRoute(async (req, res) => {
    const userId = req.user!.id
    const parsed = updateTodoSchema.safeParse(req.body)
    if (!parsed.success) {
      res.status(400).json({ error: parsed.error.errors[0].message })
      return
    }

    const todo = await updateTodo(userId, req.params.id, parsed.data)
    if (!todo) {
      res.status(404).json({ error: 'TODO를 찾을 수 없습니다.' })
      return
    }
    res.json({ todo })
  }),
)

/**
 * DELETE /api/todos/:id
 * TODO 삭제. 본인 TODO만 가능.
 */
router.delete(
  '/:id',
  requireAuth,
  asyncRoute(async (req, res) => {
    const userId = req.user!.id
    const todo = await deleteTodo(userId, req.params.id)
    if (!todo) {
      res.status(404).json({ error: 'TODO를 찾을 수 없습니다.' })
      return
    }
    res.json({ todo })
  }),
)

export default router

